"use client";
import { useState } from "react";
import { SlidersHorizontal, ArrowUpRight } from "lucide-react";
import { modelScenarios } from "@/core/finance";
import { FinancialInputsSchema, type FinancialInputs, type FinancialResult } from "@/core/types";
const defaults: FinancialInputs = { currency:"USD",price:5,variableCost:1,fixedCost:100,startingUnits:30,monthlyGrowth:.05,startingCapital:null };
export function FinanceExplorer({ finance, category }: { finance: FinancialResult; category:"software"|"physical"|"service" }) {
  const [inputs,setInputs] = useState(defaults), [scenario,setScenario] = useState("Base");
  const unit = category === "software" ? "paying customers" : category === "physical" ? "units sold" : "bookings";
  const result = FinancialInputsSchema.safeParse(inputs);
  const scenarios = result.success ? modelScenarios(result.data) : null;
  const current = scenarios?.find(s=>s.name === scenario);
  const format = (n:number) => new Intl.NumberFormat("en",{style:"currency",currency:inputs.currency,maximumFractionDigits:0}).format(n);
  function setNumber(key: keyof FinancialInputs,value: string) { setInputs(old=>({ ...old,[key]: value === "" && key === "startingCapital" ? null : Number(value) })); }
  return <div className="finance-section">{finance.status === "verified" && <div className="integration-note verified"><span className="eyebrow">CFO.AI MODEL VERIFIED</span><p>{finance.message}</p>{finance.modelUrl && <a href={finance.modelUrl} target="_blank" rel="noopener noreferrer">Open the model <ArrowUpRight size={14}/></a>}</div>}
    {finance.status === "verified" && finance.scenarios && <div className="verified-model"><h3>Saved CFO.ai scenarios</h3><div className="metric-grid">{finance.scenarios.map(s=><div key={s.name}><span>{s.name}</span><strong>{new Intl.NumberFormat("en",{style:"currency",currency:finance.inputs?.currency || "USD",maximumFractionDigits:0}).format(s.annualProfit)}</strong><small>12-month operating result</small></div>)}</div></div>}
    <div className="section-heading"><SlidersHorizontal size={20}/><div><h2>What would the numbers need to look like?</h2><p>Change a few assumptions. See which ones matter.</p></div></div><div className="finance-layout"><form className="assumption-form" onSubmit={e=>e.preventDefault()}><span className="eyebrow">YOUR ASSUMPTIONS · ALL UNSOURCED</span><label>Currency<select value={inputs.currency} onChange={e=>setInputs({...inputs,currency:e.target.value as FinancialInputs["currency"]})}>{["USD","INR","EUR","GBP"].map(c=><option key={c}>{c}</option>)}</select></label><div className="field-grid">{[{key:"price",label:category === "software" ? "Monthly price" : "Price per sale",max:1000000},{key:"variableCost",label:"Cost per customer / sale",max:1000000},{key:"startingUnits",label:`Starting ${unit}`,max:1000000},{key:"fixedCost",label:"Monthly fixed costs",max:10000000}].map(({key,label,max})=><label key={key}>{label}<input type="number" min="0" max={max} step={key === "startingUnits" ? "1" : ".01"} value={inputs[key as keyof FinancialInputs] ?? ""} onChange={e=>setNumber(key as keyof FinancialInputs,e.target.value)}/></label>)}</div><label>Monthly growth: {Math.round(inputs.monthlyGrowth*100)}%<input type="range" min="-50" max="50" step="1" value={Math.round(inputs.monthlyGrowth*100)} onChange={e=>setInputs({...inputs,monthlyGrowth:Number(e.target.value)/100})}/></label><label>Starting cash <span className="muted">(optional)</span><input type="number" min="0" max="100000000" value={inputs.startingCapital ?? ""} onChange={e=>setNumber("startingCapital",e.target.value)} placeholder="Leave blank if unknown"/></label></form><section className="scenario-output" aria-label="Financial scenario"><fieldset className="scenario-pills"><legend className="sr-only">Scenario</legend>{["Conservative","Base","Optimistic"].map(s=><label className={scenario === s ? "selected" : ""} key={s}><input type="radio" name="scenario" checked={scenario===s} onChange={()=>setScenario(s)}/>{s}</label>)}</fieldset>{current ? <><div className="metric-grid" aria-live="polite"><div><span>12-month revenue</span><strong>{format(current.annualRevenue)}</strong></div><div><span>Operating result</span><strong className={current.annualProfit < 0 ? "loss" : ""}>{format(current.annualProfit)}</strong></div></div><div className="chart" aria-label="Monthly revenue, twelve months" role="img">{current.months.map(m=><div className="chart-column" key={m.month}><span className="chart-bar" style={{height:`${Math.max(2, m.revenue / Math.max(...current.months.map(x=>x.revenue),1) * 145)}px`}} title={`Month ${m.month}: ${format(m.revenue)}`}/><span>{m.month===1 ? "M1" : m.month===12 ? "M12" : ""}</span></div>)}</div><div className="break-even"><strong>{current.breakEvenUnits === null ? "No break-even at this price" : `${current.breakEvenUnits} ${unit} to break even monthly`}</strong><p>{current.breakEvenUnits === null ? "The price doesn’t cover each additional sale. Test price or delivery cost first." : "Before tax, acquisition costs, refunds, and other costs you haven’t entered."}</p>{inputs.startingCapital !== null && <p>Cash after 12 months: {format(current.months[11].cash!)}</p>}</div></> : <p className="error-message" role="alert">Enter non-negative, finite amounts within the input limits.</p>}</section></div><p className="fine-print">This explorer uses local calculations. It assumes constant price and costs, no churn, and monthly unit growth. All inputs are editable assumptions. It does not predict demand.</p></div>;
}
