        : [link(String(index + 1), report.sources[index].url)];
    });
    return `**${
      value.nature === "hypothesis" ? "Hypothesis" : "Observation"
    }:** ${text(value.text)}${
      references.length ? ` ${references.join(" ")}` : ""
    }`;
  };
